```json
{
  "root_causes": [
    {
      "service": "payment",
      "fault_kind": "pod_unavailable",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, attr_status_code, count(*) n FROM abnormal_traces WHERE service_name = 'payment' GROUP BY ALL",
          "claim": "Payment emits no spans at all during the abnormal window (normal had 16 Server spans)."
        },
        {
          "kind": "trace",
          "sql": "SELECT span_name, attr_status_code, count(*) n, round(avg(duration/1e6),2) avg_ms FROM abnormal_traces WHERE service_name = 'checkout' AND span_name = 'oteldemo.PaymentService/Charge' GROUP BY ALL",
          "claim": "All 46 checkout calls to PaymentService/Charge error within about 0.1 ms, with no payment-side span."
        },
        {
          "kind": "metric",
          "sql": "SELECT date_trunc('minute', time) m, metric, round(avg(value),2) v FROM abnormal_metrics_sum WHERE service_name = 'payment' AND metric = 'container.cpu.time' GROUP BY ALL ORDER BY m",
          "claim": "Payment container CPU time drops from about 128 to about 0.02 from 03:26 onward and stays flat."
        },
        {
          "kind": "metric",
          "sql": "SELECT date_trunc('minute', time) m, metric, round(avg(value),0) v FROM abnormal_metrics_sum WHERE service_name = 'payment' AND metric = 'k8s.pod.uptime' GROUP BY ALL ORDER BY m",
          "claim": "Payment pod uptime keeps increasing with no reset, so it did not restart and stayed gone."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "payment",
      "to": "checkout",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.service_name, c.span_name, c.attr_status_code, count(*) n FROM abnormal_traces c WHERE c.span_name = 'oteldemo.PaymentService/Charge' GROUP BY ALL",
          "claim": "Checkout's PaymentService/Charge client spans fail with Error status in abnormal period."
        }
      ]
    },
    {
      "from": "checkout",
      "to": "frontend",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, attr_status_code, attr_http_response_status_code code, count(*) n FROM abnormal_traces WHERE service_name = 'frontend' AND span_name = 'POST /api/checkout' GROUP BY ALL",
          "claim": "Frontend POST /api/checkout Server spans return HTTP 500 in 45 abnormal requests, none in normal."
        }
      ]
    },
    {
      "from": "frontend",
      "to": "frontend-proxy",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, attr_status_code, attr_http_response_status_code code, count(*) n FROM abnormal_traces WHERE service_name = 'frontend-proxy' AND attr_span_kind = 'Server' AND attr_http_response_status_code >= 500 GROUP BY ALL",
          "claim": "Frontend-proxy ingress returns 500 for 116 abnormal requests, up from 18 in normal."
        }
      ]
    }
  ]
}
```

